# Read one line of brackets: ( ) [ ] { }
# Print "Balanced" or "Not balanced".

# Write your code here

hints.3:
pairs = {')': '(', ']': '[', '}': '{'}
stack = []
ok = True
for c in input().strip():
    if c in '([{':
        stack.append(c)
    elif not stack or stack.pop() != pairs[c]:
        ok = False
        break
print('Balanced' if ok and not stack else 'Not balanced')
